/**
 * A {@link GFileSystem} implementation giving access to the user's operating system's
 * local file system.
 * <p>
 * This implementation does not have a {@link GFileSystemFactory} as
 * this class will be used as the single root filesystem.
 * <p>
 * Closing() this filesystem does nothing.
 */
/* @FileSystemInfo(type = LocalFileSystem.FSTYPE, description = "Local filesystem", factory = typeof(GFileSystemFactoryIgnore)) */
public class LocalFileSystem : GFileSystem, GFileHashProvider {
	public static readonly string FSTYPE = "file";

	/**
	 * Create a new instance
	 *
	 * @return new {@link LocalFileSystem} instance using {@link #FSTYPE} as its FSRL type.
	 */
	public static LocalFileSystem makeGlobalRootFS() {
		return new LocalFileSystem(FSRLRoot.makeRoot(FSTYPE));
	}

	private FSRLRoot fsFSRL;
	private GFile rootDir;
	private FileSystemRefManager refManager = new FileSystemRefManager(this);
	private ReferenceMap<FileFingerprintRec, string> fileFingerprintToMD5Map =
		new();
	private bool isWindows =
		OperatingSystem.CURRENT_OPERATING_SYSTEM == OperatingSystem.WINDOWS;

	private LocalFileSystem(FSRLRoot fsrl) {
		this.fsFSRL = fsrl;
		this.rootDir = GFileImpl.fromFSRL(this, null, fsFSRL.withPath("/"), true, -1);
	}

	bool isSameFS(FSRL fsrl) {
		return fsFSRL.equals(fsrl.getFS());
	}

	/**
	 * Returns true if the {@link FSRL} is a local filesystem subdirectory.
	 *
	 * @param fsrl {@link FSRL} to test.
	 * @return boolean true if local filesystem directory.
	 */
	public bool isLocalSubdir(FSRL fsrl) {
		if (!isSameFS(fsrl)) {
			return false;
		}
		File localFile = new File(fsrl.getPath());
		return localFile.isDirectory();
	}

	/**
	 * Convert a FSRL that points to this file system into a java {@link File}.
	 * 
	 * @param fsrl {@link FSRL}
	 * @return {@link File}
	 * @throws IOException if FSRL does not point to this file system
	 */
	public File getLocalFile(FSRL fsrl)
    {
		if (!isSameFS(fsrl)) {
			throw new IOException("FSRL does not specify local file: " + fsrl);
		}
		File localFile = new File(fsrl.getPath());
		return localFile;
	}

	/**
	 * Converts a {@link File} into a {@link FSRL}.
	 * <p>
	 * NOTE: The given {@link File}'s absolute path will be used.
	 * 
	 * @param f The {@link File} to convert to an {@link FSRL}
	 * @return The {@link FSRL}
	 */
	public FSRL getLocalFSRL(File f) {
		string absPath = f.getAbsolutePath();
		if (isWindows) {
			// only force on windows... unix paths can have backslashes as part of filenames
			absPath = FilenameUtils.separatorsToUnix(absPath);
		}
		string fsrlPath = FSUtilities.appendPath("/", absPath);
		return fsFSRL.withPath(fsrlPath);
	}

	public GFile getGFile(File f) {
		List<File> parts = LocalFileSystem.getFilePathParts(f); // [/subdir/subroot/file, /subdir/subroot, /subdir, /]
		GFile current = rootDir;
		for (int i = parts.size() - (isWindows ? 1 : 2); i >= 0; i--) {
			File part = parts.get(i);
			FSRL childFSRL = getLocalFSRL(part);
			current =
				GFileImpl.fromFSRL(this, current, childFSRL, part.isDirectory(), part.length());
		}
		return current;
	}

	/* @Override */
	public string getName() {
		return "Root Filesystem";
	}

	/* @Override */
	public void close() {
		// nada
	}

	/* @Override */
	public bool isStatic() {
		return false;
	}

	/* @Override */
	public List<GFile> getListing(GFile directory) {
		List<GFile> results = new();
		directory = Objects.requireNonNullElse(directory, rootDir);

		if (directory.equals(rootDir) && isWindows) {
			foreach (File f in File.listRoots()) {
				results.add(GFileImpl.fromFSRL(this, null, getLocalFSRL(f), f.isDirectory(), -1));
			}
		}
		else {
			File localDir = new File(directory.getPath());
			if (!localDir.isDirectory() || FSUtilities.isSymlink(localDir)) {
				return List.of();
			}

			File[] files = localDir.listFiles();
			if (files == null) {
				return List.of();
			}

			foreach (File f in files) {
				if (f.isFile() || f.isDirectory() || FSUtilities.isSymlink(f)) {
					FSRL newFileFSRL = directory.getFSRL().appendPath(f.getName());
					results.add(GFileImpl.fromFSRL(this, directory, newFileFSRL, f.isDirectory(),
						f.length()));
				}
			}
		}

		return results;
	}

	/* @Override */
	public FileAttributes getFileAttributes(GFile file, TaskMonitor monitor) {
		File f = new File(file.getPath());
		return getFileAttributes(f);
	}

	/* @Override */
	public FileType getFileType(GFile f, TaskMonitor monitor) {
		return FSUtilities.getFileType(new File(f.getPath()));
	}

	/**
	 * Create a {@link FileAttributes} container with info about the specified local file.
	 * 
	 * @param f {@link File} to query
	 * @return {@link FileAttributes} instance
	 */
	public FileAttributes getFileAttributes(File f) {
		FileType fileType = FSUtilities.getFileType(f);
		string symLinkDest = fileType == FileType.SYMBOLIC_LINK ? FSUtilities.readSymlink(f) : null;
		return FileAttributes.of(
			FileAttribute.create(NAME_ATTR, f.getName()),
			FileAttribute.create(FILE_TYPE_ATTR, fileType),
			FileAttribute.create(SIZE_ATTR, f.length()),
			FileAttribute.create(MODIFIED_DATE_ATTR, new Date(f.lastModified())),
			symLinkDest != null ? FileAttribute.create(SYMLINK_DEST_ATTR, symLinkDest) : null);
	}

	/* @Override */
	public FSRLRoot getFSRL() {
		return fsFSRL;
	}

	/* @Override */
	public GFile getRootDir() {
		return rootDir;
	}

	/* @Override */
	public GFile lookup(string path)
    {
		return lookup(path, null);
	}

	/* @Override */
	public GFile lookup(string path, Comparator<string> nameComp)
    {
		if (path == null || path.equals(rootDir.getPath() /* should be "/" */)) {
			return rootDir;
		}
		File f = lookupFile(null, path, nameComp);
		return f != null ? getGFile(f) : null;
	}

	/* @Override */
	public bool isClosed() {
		return false;
	}

	/* @Override */
	public FileSystemRefManager getRefManager() {
		return refManager;
	}

	/* @Override */
	public InputStream getInputStream(GFile file, TaskMonitor monitor)
    {
		return getInputStream(file.getFSRL(), monitor);
	}

	InputStream getInputStream(FSRL fsrl, TaskMonitor monitor)
    {
		return new FileInputStream(getLocalFile(fsrl));
	}

	/* @Override */
	public ByteProvider getByteProvider(GFile file, TaskMonitor monitor)
    {
		return getByteProvider(file.getFSRL(), monitor);
	}

	ByteProvider getByteProvider(FSRL fsrl, TaskMonitor monitor)
    {
		File f = getLocalFile(fsrl);
		return new FileByteProvider(f, fsrl, AccessMode.READ);
	}

	/* @Override */
	public GFile resolveSymlinks(GFile file)
    {
		File f = getLocalFile(file.getFSRL());
		File canonicalFile = f.getCanonicalFile();
		if (f.equals(canonicalFile)) {
			return file;
		}
		return getGFile(canonicalFile);
	}

	/* @Override */
	public string toString() {
		return "Local file system " + fsFSRL;
	}

	/* @Override */
	public string getMD5Hash(GFile file, bool required, TaskMonitor monitor)
    {
		return getMD5Hash(file.getFSRL(), required, monitor);
	}

	string getMD5Hash(FSRL fsrl, bool required, TaskMonitor monitor)
    {
		File f = getLocalFile(fsrl);
		if ( !f.isFile() ) {
			return null;
		}
		
		FileFingerprintRec fileFingerprintRec = new FileFingerprintRec(f.getPath(), f.lastModified(), f.length());
		string md5 = fileFingerprintToMD5Map.get(fileFingerprintRec);
		if (md5 == null && required) {
			md5 = FSUtilities.getFileMD5(f, monitor);
			fileFingerprintToMD5Map.put(fileFingerprintRec, md5);
		}
		
		return md5;
	}

